window.__posterData({"id": "otto-ekerman", "name": "Otto Ekerman", "folder": "Week3_Poster_OttoEkerman_Final", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "//Comments from last version/made by AI = ()\n// (Images)\nlet image1;\nlet image2;\nlet image3;\nlet image4;\nlet image5;\n\n//New image array\nlet imageArray = [];\nlet currentImage;\nlet currentS;\n\n// Some new variables for audio, part of what I asked it for with the filter\n// (Audio)\nlet audioContext;\nlet audioFilter;\nlet loop1;\nlet loop2;\nlet activeSource = null;\nlet playingLoop = 0;\n\n//New variables\n// (Loading state)\nlet ready = false;\nlet loadingError = \"\";\n\n//New code for AI-suggested signal tear\n// (Occasional horizontal signal tears)\nlet nextSignalTear = 0;\nlet signalTearEnds = 0;\nlet signalSlices = [];\n\n// (Load images and audio.)\nasync function setup() {\n  createCanvas(600, 800);\n//New instance of AudioContext, never heard of before\n  try {\n    audioContext = new AudioContext();\n//Refactored code, haven't seen this syntax before\n    [\n      image1,\n      image2,\n      image3,\n      image4,\n      image5,\n      loop1,\n      loop2\n    ] = await Promise.all([\n      loadImage(\"thisman1.jpg\"),\n      loadImage(\"thisman2.jpg\"),\n      loadImage(\"thisman3.jpeg\"),\n      loadImage(\"thisman4.jpg\"),\n      loadImage(\"thisman5.jpeg\"),\n      loadAudioBuffer(\"loop1.mp3\"),\n      loadAudioBuffer(\"loop2.mp3\")\n    ]);\n\n    imageArray = [image1, image2, image3, image4, image5];\n    currentImage = image1;\n    currentS = second();\n    // Code for filter\n    // (Route audio through a low-pass filter.)\n    audioFilter = audioContext.createBiquadFilter();\n    audioFilter.type = \"lowpass\";\n    audioFilter.connect(audioContext.destination);\n\n    updateAudioFilter(true);\n    // I think this is for making sure it runs correctly, because of browser restrictions\n    // (Schedule loop1. Browsers may require a click to hear it.)\n    startLoop(1);\n    ready = true;\n  } catch (error) {\n    console.error(error);\n    loadingError = \"Could not load assets. Check filenames and paths.\";\n  }\n}\n\n// New audio code, don't understand what it does besides decoding the audio\n// (Load and decode an audio file.)\nasync function loadAudioBuffer(path) {\n  const response = await fetch(path);\n\n  if (!response.ok) {\n    throw new Error(`Could not load ${path}: ${response.status}`);\n  }\n\n  const data = await response.arrayBuffer();\n  return await audioContext.decodeAudioData(data);\n}\n\n//Refactored code for the audio loops.\n// (Start one loop and stop the previous loop.)\nfunction startLoop(number) {\n  if (activeSource) {\n    activeSource.stop();\n    activeSource.disconnect();\n  }\n\n  activeSource = audioContext.createBufferSource();\n  activeSource.buffer = number === 1 ? loop1 : loop2;\n  activeSource.loop = true;\n  activeSource.connect(audioFilter);\n  activeSource.start();\n\n  playingLoop = number;\n\n  if (number === 2) {\n    currentImage = random(imageArray);\n    currentS = second();\n  }\n}\n\n// I think it added this for it to run correctly as well, because of browser restrictions\n// (First click unlocks audio; later clicks switch loops.)\nasync function mousePressed() {\n  if (!ready) return;\n\n  if (audioContext.state !== \"running\") {\n    await audioContext.resume();\n    return;\n  }\n\n  startLoop(playingLoop === 1 ? 2 : 1);\n}\n// The actual filter for the audio. Alot of new syntax.\n// (Mouse-controlled cutoff and resonance.)\nfunction updateAudioFilter(immediate = false) {\n  if (!audioFilter) return;\n\n  const x = constrain(mouseX / width, 0, 1);\n  const y = constrain(mouseY / height, 0, 1);\n\n  const minCutoff = 500;\n  const maxCutoff = min(20000, audioContext.sampleRate * 0.45);\n\n  // (Left = 500 Hz; right = up to 20 kHz.\n  // Logarithmic mapping gives a natural frequency sweep.)\n  const cutoff = minCutoff * pow(maxCutoff / minCutoff, x);\n\n  // (Bottom = no resonance boost; top = +12 dB peak.)\n  const peakDb = 12 * (1 - y);\n\n  // (Convert the desired peak gain into a quality factor.)\n  const amplitude = pow(10, peakDb / 20);\n  const amplitudeSquared = amplitude * amplitude;\n\n  const q = sqrt(\n    (\n      amplitudeSquared +\n      amplitude * sqrt(max(0, amplitudeSquared - 1))\n    ) / 2\n  );\n\n  // (Web Audio's low-pass Q parameter uses decibels.)\n  const qDb = 20 * Math.log10(q);\n  const now = audioContext.currentTime;\n\n  if (immediate) {\n    audioFilter.frequency.setValueAtTime(cutoff, now);\n    audioFilter.Q.setValueAtTime(qDb, now);\n  } else {\n    // (Smooth changes to prevent abrupt parameter jumps.)\n    audioFilter.frequency.setTargetAtTime(cutoff, now, 0.02);\n    audioFilter.Q.setTargetAtTime(qDb, now, 0.02);\n  }\n}\n\n//Very simillar to the code I wrote\n// (Draw the poster typography.)\nfunction createText() {\n  noStroke();\n  textFont(\"helvetica\");\n  textStyle(BOLD);\n  textAlign(CENTER, BASELINE);\n\n  textSize(110);\n  fill(mouseX, 0, random(255));\n  text(\"DOHN JOE\", width / 2, height / 2 - 70);\n\n  textSize(38);\n  text(\n    `${floor(mouseY)} signs your horse is a healer`,\n    width / 2,\n    height / 2 + 30\n  );\n\n  if (playingLoop === 2) {\n    fill(mouseY, random(150), mouseX);\n    text(\"Ever dream this algorithm?\", width / 2, 700);\n  }\n\n  // (Visual blur, separate from the audio filter.)\n  filter(BLUR, random(5));\n}\n\n//Also simillar to the code I wrote\n// (Change background once per second while loop2 plays.)\nfunction setBackgroundImage() {\n  if (playingLoop === 2) {\n    if (currentS !== second()) {\n      currentS = second();\n      currentImage = random(imageArray);\n    }\n\n    background(currentImage);\n    createSquares();\n  } else {\n    background(image1);\n  }\n\n  // (Transparent green overlay.)\n  background(0, 255, 0, 210);\n}\n\n// (Draw squares that act like grain.)\nfunction createSquares() {\n  noStroke();\n  fill(255, 255, 255, 150);\n\n  for (let i = 0; i < 50; i++) {\n    rect(random(width), random(height), 10, 10);\n  }\n}\n\n// Code for the signal tear\n// (Briefly shift horizontal slices of the poster sideways.)\nfunction drawSignalTear() {\n  const now = millis();\n\n  // (Schedule the first tear after a short pause.)\n  if (nextSignalTear === 0) {\n    nextSignalTear = now + random(2500, 5500);\n  }\n\n  // (Create a new distortion every 2.5–5.5 seconds.)\n  if (now >= nextSignalTear) {\n    signalTearEnds = now + random(80, 160);\n    nextSignalTear = now + random(2500, 5500);\n\n    signalSlices = [];\n\n    for (let i = 0; i < floor(random(2, 5)); i++) {\n      signalSlices.push({\n        y: floor(random(height)),\n        h: floor(random(3, 18)),\n        offset: floor(random(5, 19)) * (random() < 0.5 ? -1 : 1)\n      });\n    }\n  }\n\n  if (now >= signalTearEnds) return;\n\n  // (Capture the finished poster, including its text.)\n  const posterFrame = get();\n\n  push();\n  imageMode(CORNER);\n  noTint();\n\n  for (const slice of signalSlices) {\n    const sliceHeight = min(slice.h, height - slice.y);\n\n    // (Wrap the shifted strip around the canvas edges.)\n    for (const wrap of [-width, 0, width]) {\n      image(\n        posterFrame,\n        slice.offset + wrap,\n        slice.y,\n        width,\n        sliceHeight,\n        0,\n        slice.y,\n        width,\n        sliceHeight\n      );\n    }\n  }\n\n  pop();\n}\n\n//Refactored draw, it added the error display as well in refactoring\nfunction draw() {\n  if (!ready) {\n    background(0);\n    fill(255);\n    noStroke();\n    textFont(\"helvetica\");\n    textStyle(NORMAL);\n    textAlign(CENTER, CENTER);\n    textSize(20);\n\n    text(\n      loadingError || \"Loading...\",\n      width / 2,\n      height / 2\n    );\n\n    return;\n  }\n\n  updateAudioFilter();\n  setBackgroundImage();\n  createText();\n\n  // (Apply occasional signal tears to the finished poster.)\n  drawSignalTear();\n}\n\n\n//1. The code is a few lines longer after step 1, but this is because it has created additional comments for structure, like // ---------- Assets ----------.However, the AI states that there are less characters, about 8% fewer. It cut down a few functions, such as mousePressed, but added a new function called inside of it. I can understand the code it writes, I assume that it estimated my skill when refactoring. It hasn’t used any new code that I’d consider groundbreaking, but in refactoring the code it put all of my image variables in a loop, and used await inside of it. Similarly, it’s done other things that I didn’t think of, like replacing imageArray[floor(random(imageArray.length))] with random(imageArray).\n\n//2. The prompt for stage 2 was “I want you to create an audio filter following the mouse coordinates. I want the X-axis to control cutoff, and the Y-axis to control the gain of the resonance. I don't want to filter to be able to cut below 500 Hz, and I don't want the gain to be able to go higher than +12 dB.” I think this worked well.\n\n//3. The AIs own addition wasn't much to my liking. The first suggestion it gave was a trail of \"ghost faces\" (the thisman image) following the cursor and fading out. I thought it was tacky and didn't really fit the aesthetic. I told it that I thought it was tacky and instead it gave me the signal tear visual. I think it fits well, it isn't a major addition, but it definately created more complex code. Overall I'm happy with the filter, but not very impressed with the AIs own addition. I think it goes to show that when left to its own devices it's not very useful for creating something meaningful creatively, according to me.", "assets": {"loop1.mp3": {"mime": "audio/mpeg", "b64": ""}, "thisman1.jpg": {"mime": "image/webp", "b64": ""}, "thisman2.jpg": {"mime": "image/webp", "b64": ""}, "thisman3.jpeg": {"mime": "image/webp", "b64": ""}, "loop2.mp3": {"mime": "audio/mpeg", "b64": ""}, "thisman5.jpeg": {"mime": "image/webp", "b64": ""}, "thisman4.jpg": {"mime": "image/webp", "b64": ""}}});
